import sys

def count_awesome_substrings(s):
    n = len(s)
    count = 0
    prefix_sum = [0] * (n + 1)

    for i in range(n):
        prefix_sum[i + 1] = prefix_sum[i] + (s[i] == '1')

    for start in range(n):
        for end in range(start + 1, n + 1):
            length = end - start
            ones_count = prefix_sum[end] - prefix_sum[start]
